document.addEventListener("DOMContentLoaded",function(){var burger=document.querySelector(".burger");var actions=document.querySelector(".header-actions");if(burger && actions){burger.addEventListener("click",function(){actions.classList.toggle("open");});}var qtyBoxes=document.querySelectorAll(".qty-row");qtyBoxes.forEach(function(box){var minus=box.querySelector(".qty-minus");var plus=box.querySelector(".qty-plus");var value=box.querySelector(".qty-value");if(!minus || !plus || !value)return;minus.addEventListener("click",function(){var current=parseInt(value.textContent,10);if(current>1)value.textContent=current - 1;});plus.addEventListener("click",function(){var current=parseInt(value.textContent,10);value.textContent=current+1;});});});